sys_ws_operation.operation_script:
(function process(request, response) {
    if (!(gs.hasRole('x_espaco.leitura') || gs.hasRole('x_espaco.recepcionista') ||
          gs.hasRole('x_espaco.profissional') || gs.hasRole('x_espaco.gestor') || gs.hasRole('x_espaco.admin'))) {
        response.setStatus(403);
        return { error: { code: 403, message: 'Sem permissão para consultar este recurso.' } };
    }
    var page = parseInt(request.queryParams.page || '1', 10);
    var limit = Math.min(parseInt(request.queryParams.limit || '20', 10), 100);
    var offset = (page - 1) * limit;

    var gr = new GlideRecord('x_espaco_agendamento');
    if (request.queryParams.data) {
        gr.addQuery('data_hora', 'ON', request.queryParams.data);
    }
    if (request.queryParams.profissionalId) {
        gr.addQuery('profissional', request.queryParams.profissionalId);
    }
    if (request.queryParams.clienteId) {
        gr.addQuery('cliente', request.queryParams.clienteId);
    }
    gr.orderByDesc('data_hora');
    gr.chooseWindow(offset, offset + limit);
    gr.query();

    var data = [];
    while (gr.next()) {
        data.push({
            sys_id: gr.getUniqueValue(),
            cliente: gr.getValue('cliente'),
            servico: gr.getValue('servico'),
            profissional: gr.getValue('profissional'),
            data_hora: gr.getValue('data_hora'),
            status: gr.getValue('status'),
            penalidade: gr.getValue('penalidade')
        });
    }

    var count = new GlideAggregate('x_espaco_agendamento');
    if (request.queryParams.data) {
        count.addQuery('data_hora', 'ON', request.queryParams.data);
    }
    if (request.queryParams.profissionalId) {
        count.addQuery('profissional', request.queryParams.profissionalId);
    }
    if (request.queryParams.clienteId) {
        count.addQuery('cliente', request.queryParams.clienteId);
    }
    count.addAggregate('COUNT');
    count.query();
    var total = count.next() ? parseInt(count.getAggregate('COUNT'), 10) : 0;

    response.setStatus(200);
    return { data: data, meta: { page: page, limit: limit, total: total } };
})(request, response);
